const B = ['b', 'u1', '2026-10-01T09:00:00.000Z'] as const;
const C = ['c', 'u1', '2026-10-01T10:00:00.000Z'] as const;
const OTHER = ['z', 'u2', '2026-10-01T11:00:00.000Z'] as const;

